curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>&types=public_channel&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for channel in data.get('channels', []):
        if 'payments' in channel.get('name', '').lower():
            print(channel['id'] + ' | ' + channel['name'] + ' | ' + channel.get('topic', {}).get('value', ''))
else:
    print('Error:', data.get('error'))
"

